import sqlite3, json
conn = sqlite3.connect('world.db')
conn.row_factory = sqlite3.Row
# Search for all direct flights from JFK to MIA
cursor = conn.execute("""
SELECT * FROM flights
WHERE origin = 'JFK' AND destination = 'MIA' AND stops = 0
AND source_skill = 'tau2Airline'
""")
rows = cursor.fetchall()
print(f"Total direct JFK→MIA flights found: {len(rows)}\n")
for row in rows:
d = dict(row)
print(f"--- Flight {d['flight_id']} ---")
for key, val in d.items():
if key.endswith('_json'):
try:
parsed = json.loads(val)
print(f"  {key}: {json.dumps(parsed, indent=2)}")
except:
print(f"  {key}: {val}")
else:
print(f"  {key}: {val}")
# Check if 2026-09-20 is available
dates = json.loads(d['dates_json'])
if '2026-09-20' in dates:
date_info = dates['2026-09-20']
print(f"\n  >>> Available on 2026-09-20: YES")
print(f"  >>> Status on that date: {date_info.get('status', 'N/A')}")
print(f"  >>> Prices: {json.dumps(date_info.get('prices', {}), indent=4)}")
print(f"  >>> Available seats: {json.dumps(date_info.get('available_seats', {}), indent=4)}")
else:
print(f"\n  >>> Available on 2026-09-20: NO")
print()
conn.close()
